/**
 * Throws when a discriminated union switch is not exhaustive.
 */
export function unreachable(value) {
    throw new Error(`[custom-blocks-dev-shell] Unexpected value encountered: ${JSON.stringify(value)}`);
}
/** Lowercase, non-alphanumerics collapsed to `_`; undefined when nothing survives. */
export function slugify(name) {
    const slug = name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "");
    return slug.length > 0 ? slug : undefined;
}
/**
 * Claim `base` as a key in `used`, suffixing `_2`, `_3`, … while it is
 * already taken. Mutates `used` so later claims see this one.
 */
export function claimUniqueKey(base, used) {
    let key = base;
    for (let counter = 2; used.has(key); counter++) {
        key = `${base}_${counter}`;
    }
    used.add(key);
    return key;
}
export function parseCliArgs({ argv, handlers, onUnknown, onPositional, }) {
    const takeValue = (name, index) => {
        const value = argv[index];
        if (value === undefined || value.startsWith("--")) {
            throw new Error(`${name} requires a value.`);
        }
        return value;
    };
    for (let index = 0; index < argv.length; index++) {
        const arg = argv[index];
        const separator = arg.indexOf("=");
        const name = separator === -1 ? arg : arg.slice(0, separator);
        const handler = handlers[name];
        if (handler === undefined) {
            if (arg.startsWith("-")) {
                onUnknown(arg);
            }
            else {
                onPositional(arg);
            }
            continue;
        }
        const value = separator === -1 ? takeValue(name, ++index) : arg.slice(separator + 1);
        handler(value);
    }
}
